import{d as b,C as t,o as c,c as u,j as a,a as s,E as o,a3 as g}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第六十六章","description":"由江海处下读在上者的谦后，辨不重、不害与天下乐推的不争之意。","frontmatter":{"title":"道德经第六十六章","description":"由江海处下读在上者的谦后，辨不重、不害与天下乐推的不争之意。","category":"guide","aliases":["道德经第六十六章","老子第六十六章","dao de jing chapter 66"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-66.md","filePath":"daoism/dao-de-jing/chapter-66.md","lastUpdated":1794189804000}'),m={name:"daoism/dao-de-jing/chapter-66.md"},y=b({...m,setup(x){const n=[{id:"sea-below-the-streams",label:"江海所以能为百谷王者",showLabel:!0,sentences:[["江海所以能为",{text:"百谷",glossary:"baigu"},"王者，以其善",{text:"下",glossary:"xia"},"之，故能为",{text:"百谷",glossary:"baigu"},"王。"]],note:["【白话】江海之所以能成为众多谷水汇聚的主处，是因为它善于处在众流的下方，所以能承接百谷之水，成为百谷之王。","【读法】百谷不是百种粮谷，而是众多山谷及其水流。下之先由江海的低处说起，再引出人在关系中自处谦下的意思；可与第六十一章大国下流相参。","【读法】所据卷四本章未见逐句王注。本页依经文给出白话与阅读提示，不把别章注语移来当成本章原注。"]},{id:"words-low-self-behind",label:"欲上民，必以言下之",showLabel:!0,sentences:[["是以圣人欲",{text:"上",glossary:"shang"},"民，必以言",{text:"下",glossary:"xia"},"之；欲",{text:"先",glossary:"xian"},"民，必以身",{text:"后",glossary:"hou"},"之。"]],note:["【白话】因此，圣人若要居于百姓之上，言语就必须对他们谦下；若要处在百姓之前，就必须把自己的身位放在他们之后。","【读法】上、先、下、后都有动作意味：居上与处前，须以谦言、后身相配。经文仍从圣人居上临民的古代关系立论，不能只剩下日常礼貌。","【读法】言下与身后相连，提醒读者不只留意说得是否谦虚，也看行动中是否急于独占先位。"]},{id:"position-without-burden",label:"圣人处上而民不重",showLabel:!0,sentences:[["是以圣人处",{text:"上",glossary:"shang"},"而民不",{text:"重",glossary:"zhong"},"，处前而民不害。"]],note:["【白话】这样，圣人虽居于上位，百姓却不感到沉重的负担；虽处在前面，百姓却不觉得受到他的妨害。","【读法】不重是百姓不以为重负，不是说百姓轻浮；不害也是从民的处境来衡量居上者。此句把前面的谦下从姿态推进到实际影响。","【读法】今天相参时，可以追问居于负责位置的人是否把代价不断转给别人；这层应用应由真实影响检验。"]},{id:"welcome-support",label:"天下乐推而不厌",showLabel:!0,sentences:[["是以天",{text:"下",glossary:"xia"},{text:"乐",glossary:"le"},{text:"推",glossary:"tui"},"而不",{text:"厌",glossary:"yan"},"。"]],note:["【白话】因此，天下的人愿意推戴他，而不厌弃他。这里的拥戴，承接的是前文不使民受重负、不让民受妨害。","【读法】乐为乐意，推为推戴，厌为厌弃。不要把结果抽离前面的条件，简化成只要态度低调就必获所有人认同。"]},{id:"not-contending-for-rank",label:"以其不争",showLabel:!0,sentences:[["以其",{text:"不争",glossary:"buzheng"},"，故天",{text:"下",glossary:"xia"},"莫能与之争。"]],note:["【白话】正因为他不以争夺先位的方式对待天下，所以天下没有人能以同样的争夺方式与他相争。","【读法】末句沿用全章推尊不争的语势，说明居下、后身与乐推之间的关系。它不是一条可代入任何竞争场景、保证个人取胜的公式。","【读法】与第八章夫唯不争、第六十一章大者宜为下参读，可看见不争总与利物、承接和大者的责任相连。"]}],r=[{id:"baigu",term:"百谷",sense:1},{id:"xia",term:"下",sense:1},{id:"shang",term:"上",sense:1},{id:"xian",term:"先",sense:1},{id:"hou",term:"后",sense:1},{id:"zhong",term:"重",sense:2},{id:"le",term:"乐",sense:1},{id:"tui",term:"推",sense:1},{id:"yan",term:"厌",sense:2},{id:"buzheng",term:"不争",sense:1}];return(p,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return c(),u("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第六十六章",tabindex:"-1"},[s("道德经第六十六章 "),a("a",{class:"header-anchor",href:"#道德经第六十六章","aria-label":'Permalink to "道德经第六十六章"'},"​")],-1)),o(i,{title:"为什么江海处下，反能成为百谷之王",summary:"江海能承接众流，因为它善处于低下。本章把这个取象转入在上者与百姓的关系：言语谦下、行事退后，才使居上不成重负、在前不成伤害。天下乐推承接的是这些条件，不只是一个争得拥戴的技巧。",points:[{label:"先读",text:"由百谷归江海的取象，进入欲上民与欲先民的两组对照。"},{label:"再辨",text:"不重、不害先说百姓的感受；谦下要落实到少添重负、少施伤害。"},{label:"后看",text:"天下乐推再接不争，连看在上者如何承接众人，而不只看自己的地位。"}],hint:"百谷读 bǎi gǔ，指众谷及其水流；重读 zhòng，乐读 lè。不厌在此为不厌弃，与第五十三章饱足之厌分义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),o(l,{sections:n,glossary:r}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),o(d,{lines:[{text:"以其善下之，故能为百谷王。",tone:"低处与承接",guide:"先看江海如何容纳众流，再进入谦下与居上的关系。"},{text:"是以圣人处上而民不重，处前而民不害。",tone:"由百姓的处境检验",guide:"不只看居上者如何表态，还看他的存在是否加重负担、造成妨害。"},{text:"以其不争，故天下莫能与之争。",tone:"连回前面的条件",guide:"不争承接言下、身后、不重与不害，不单独当作获胜技巧。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),o(h,{items:r}),e[4]||(e[4]=g("",15))])}}});export{_ as __pageData,y as default};
